                        file(params.modules_testdata_base_path + 'delete_me/srst2/SRR9067271_1.fastq.gz',checkIfExists:true),
                        file(params.modules_testdata_base_path + 'delete_me/srst2/SRR9067271_2.fastq.gz',checkIfExists:true)
